User Namespaces:
// /etc/docker/daemon.json
{
  "userns-remap": "default"
}
# Maps container UIDs to host UIDs in /etc/subuid and /etc/subgid
# ps aux shows container processes owned by remapped user

gVisor:
# Install gVisor, then configure as runtime
# /etc/docker/daemon.json
{
  "runtimes": {
    "runsc": {
      "path": "/usr/bin/runsc",
      "runtimeArgs": ["--platform=kvm"]
    }
  }
}

docker run --runtime=runsc nginx

