Graceful Shutdown:
# Handle SIGTERM in Node.js:
process.on('SIGTERM', () => {
  server.close(() => process.exit(0));
});

# Use dumb-init (Dockerfile):
RUN apk add --no-cache dumb-init
ENTRYPOINT ["/usr/bin/dumb-init", "--"]
CMD ["node", "server.js"]

Namespaces:
// Docker creates these namespaces per container:
// PID namespace: process tree isolation (PID 1 inside != PID 1 on host)
// NET namespace: own interfaces, routing, iptables
// MNT namespace: isolated mount table
// UTS namespace: own hostname/domain
// IPC namespace: System V IPC + POSIX message queues
// USER namespace: root inside maps to non-root outside

// Inspect namespace IDs on host:
lsns -p 1                # list namespaces of PID 1
ls -la /proc/1/ns/       # see namespace inodes

Cgroups:
// cgroup v2 hierarchy under /sys/fs/cgroup/
// Docker creates a cgroup per container:
//   /sys/fs/cgroup/system.slice/docker-<id>.scope/

// Read CPU quota for a running container:
cat /sys/fs/cgroup/system.slice/docker-<id>.scope/cpu.max

// Set limits at runtime (mapped to cgroup writes):
docker run --cpus=1.5 --memory=512m --memory-swap=1g nginx

// View cgroup stats:
docker stats <container>

OCI Spec & containerd:
// Docker architecture stack:
//   dockerd -> containerd (via CRI) -> runc (via OCI bundle)
//   - containerd: manages image pull, snapshots, container lifecycle
//   - runc: creates OCI bundle from spec, spawns container via clone()
//   - OCI Image Spec: standardizes image manifest, config, layers
//   - OCI Runtime Spec: standardizes config.json (namespaces, cgroups, mounts)

// Generate OCI bundle manually:
mkdir /tmp/oci-bundle && cd /tmp/oci-bundle
mkdir rootfs && docker export $(docker create alpine) | tar xf - -C rootfs
runc spec                 # generates config.json
# Edit config.json (set process.args, root.path, etc.)
runc run mycontainer

// View the config.json that runc would use:
docker inspect <container> | jq '.[0].HostConfig'

Overlay2 Storage Deep:
// Overlay2 directory structure on disk:
//   /var/lib/docker/overlay2/
//     <layer-hash>/      each image layer
//       diff/              actual files in this layer
//       link               short name link
//       lower              parent layer references
//     l/                  short symlinks to active layers
//     <container-id>/     container-specific merged view
//       merged/            final merged view (read-write)
//       upper/             writable layer (container changes)
//       work/              internal overlayfs workdir

// Check storage driver usage:
docker info | grep -A2 "Storage Driver"

// See which layers an image uses:
docker image inspect alpine:latest | jq '.[0].GraphDriver.Data'

Veth Pairs & Bridge Forwarding:
// veth pair = virtual Ethernet cable with two ends:
//   - eth0 inside container (namespace side)
//   - vethXXXXX on host (bridge side)
// Both ends are always connected; traffic in one end = out the other

// Inspect veth pairs on the host:
ip link show type veth          # list all veth interfaces
bridge link show                # show which veth on docker0

// Watch ARP and forwarding:
ip neigh                          # neighbor table on host
bridge fdb show                  # forwarding database

// Test bridge forwarding:
docker run --rm alpine ping 8.8.8.8   # goes: eth0 -> veth -> docker0 -> iptables MASQUERADE -> eth0 host

iptables & NAT:
// Docker's iptables chains (filter and nat tables):
//   - DOCKER chain: per-container DNAT rules for published ports
//   - DOCKER-USER chain: USER-DEFINED rules evaluated before DOCKER
//   - MASQUERADE: container -> internet via host IP
//   - FORWARD: default DROP, Docker adds ACCEPT for container traffic

// See Docker iptables rules:
iptables -t nat -L -n | grep DOCKER          # NAT rules
iptables -L DOCKER -n                        # filter rules
iptables -L FORWARD -n                       # forwarding rules

// Add custom rules that Docker won't override:
iptables -I DOCKER-USER -p tcp --dport 8080 -j DROP

// Disable Docker's iptables management entirely:
// daemon.json: { "iptables": false }

Structured Logging:
// Node.js structured logging (pino):
const pino = require('pino');
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
logger.info({ user: 'abc', action: 'login' }, 'user logged in');

// Configure Docker logging driver to forward structured logs:
docker run \
  --log-driver loki \
  --log-opt loki-url=http://loki:3100/loki/api/v1/push \
  myapp

// Or use json-file driver with log rotation:
docker run \
  --log-driver json-file \
  --log-opt max-size=10m \
  --log-opt max-file=3 \
  --log-opt labels=env,service \
  myapp

// NEVER log to files; they're lost when the container dies
// Instead: always log to STDOUT/STDERR
